32	export class AuthService {
33	  private static async clearCryptoStore() {
34	    try {
35	      const dataExists = await RNFS.exists(dataPath);
36	      const cacheExists = await RNFS.exists(cachePath);
37	
38	      if (dataExists) {
39	        await RNFS.unlink(dataPath);
40	        console.log("Cleared crypto data store");
41	      }
42	
43	      if (cacheExists) {
44	        await RNFS.unlink(cachePath);
45	        console.log("Cleared crypto cache store");
46	      }
47	    } catch (error) {
48	      console.warn("Failed to clear crypto store:", error);
49	    }
50	  }
