52	  /** Full init for first login — does server discovery (requires network). */
53	  public static initialize = async (serverUrl: string) => {
54	    MatrixCore.instance = await new ClientBuilder()
55	      .serverNameOrHomeserverUrl(serverUrl)
56	      .sessionPaths(dataPath, cachePath)
57	      .autoEnableCrossSigning(true)
58	      .autoEnableBackups(false)
59	      .backupDownloadStrategy(BackupDownloadStrategy.AfterDecryptionFailure)
60	      .build();
61	  };
62	
63	  /**
64	   * Offline-capable init for session restore.
65	   * Uses the exact homeserver URL + known username so no server discovery is needed.
66	   */
67	  private static initializeForRestore = async (
68	    homeserverUrl: string,
69	    userId: string,
70	  ) => {
71	    MatrixCore.instance = await new ClientBuilder()
72	      .homeserverUrl(homeserverUrl)
73	      .username(userId)
74	      .slidingSyncVersionBuilder(SlidingSyncVersionBuilder.Native)
75	      .sessionPaths(dataPath, cachePath)
76	      .autoEnableCrossSigning(true)
77	      .autoEnableBackups(false)
78	      .backupDownloadStrategy(BackupDownloadStrategy.AfterDecryptionFailure)
79	      .build();
80	  };
81	
82	  public static hasStoredCredentials = (): boolean => {
83	    return MatrixStorage.hasStoredCredentials();
84	  };
85	
86	  public static getServerName = () => MatrixCore.getServerName();
87	
88	  public static getUser = () => {
89	    if (!MatrixCore.instance) return null;
90	    const userId = MatrixCore.instance.userId();
91	    return userId ? MatrixCore.instance.getProfile(userId) : null;
92	  };
93	
94	  public static restoreSessionForBackground = async (): Promise<boolean> => {
95	    try {
96	      if (
97	        MatrixCore.instance &&
98	        MatrixNotificationService.getNotificationClient()
99	      )
100	        return true;
101	
102	      const credentials = MatrixStorage.getLoginCredentials();
103	      if (!credentials) return false;
104	
105	      // Use the same offline-safe init as foreground so the client is compatible
106	      // if the foreground reuses this instance (same file paths, same sync config).
107	      await this.initializeForRestore(credentials.baseUrl, credentials.userId);
108	
109	      const client = MatrixCore.getClient();
110	
111	      await client.restoreSession({
112	        accessToken: credentials.accessToken,
113	        refreshToken: credentials.refreshToken,
114	        userId: credentials.userId,
115	        deviceId: credentials.deviceId,
116	        homeserverUrl: credentials.baseUrl,
117	        oidcData: undefined,
118	        slidingSyncVersion: SlidingSyncVersion.Native,
119	      });
120	
121	      await client.encryption().waitForE2eeInitializationTasks();
122	
123	      await MatrixNotificationService.ensureNotificationClient();
124	
125	      return true;
126	    } catch (error) {
127	      console.error("[Background] Failed to restore session:", error);
128	      return false;
129	    }
130	  };
131	
132	  public static restoreSession = async (): Promise<boolean> => {
133	    try {
134	      const credentials = MatrixStorage.getLoginCredentials();
135	      if (!credentials) return false;
136	
137	      // If the background handler already initialized and restored the client,
138	      // reuse it — creating a second client on the same file paths would
139	      // conflict with the existing native SDK file locks and cause a hang.
140	      if (!MatrixCore.instance) {
141	        // Use offline-capable init: direct homeserver URL + known username,
142	        // no server discovery needed.
143	        await this.initializeForRestore(
144	          credentials.baseUrl,
145	          credentials.userId,
146	        );
147	
148	        const client = MatrixCore.getClient();
149	
150	        await client.restoreSession({
151	          accessToken: credentials.accessToken,
152	          refreshToken: credentials.refreshToken,
153	          userId: credentials.userId,
154	          deviceId: credentials.deviceId,
155	          homeserverUrl: credentials.baseUrl,
156	          oidcData: undefined,
157	          slidingSyncVersion: SlidingSyncVersion.Native,
158	        });
159	      }
160	
161	      const client = MatrixCore.getClient();
162	
163	      // Profile fetch may fail when offline — don't block session restore on it.
164	      try {
165	        const profile = await client.getProfile(credentials.userId);
166	        MatrixJotaiStore.set(StorageAtoms.cachedProfile, profile);
167	      } catch {}
168	
169	      // withOfflineMode() serves cached rooms immediately without waiting for network.
170	      MatrixCore.syncService = await client
171	        .syncService()
172	        .withOfflineMode()
173	        .finish();
174	
175	      if (!MatrixCore.syncService) {
176	        throw new Error("Failed to initialize sync service");
177	      }
178	
179	      MatrixJotaiStore.set(MatrixAtoms.matrixClient, MatrixCore.instance);
180	      MatrixJotaiStore.set(MatrixAtoms.syncService, MatrixCore.syncService);
181	
182	      return true;
183	    } catch (error) {
184	      console.warn("Failed to restore session:", error);
185	
186	      MatrixCore.instance = null;
187	      MatrixCore.syncService = null;
188	
189	      MatrixJotaiStore.set(MatrixAtoms.matrixClient, null);
190	      MatrixJotaiStore.set(MatrixAtoms.syncService, null);
191	
192	      return false;
193	    }
194	  };
195	
196	  /** Start (or resume) the Matrix sync loop. No-op if the sync service is not ready. */
197	  public static startSync = async (): Promise<void> => {
198	    if (!MatrixCore.syncService) return;
199	    try {
200	      await MatrixCore.syncService.start();
201	    } catch (error) {
202	      console.warn("Failed to start sync:", error);
203	    }
204	  };
205	
206	  /** Stop the Matrix sync loop. No-op if the sync service is not ready. */
207	  public static stopSync = async (): Promise<void> => {
208	    if (!MatrixCore.syncService) return;
209	    try {
210	      await MatrixCore.syncService.stop();
211	    } catch (error) {
212	      console.warn("Failed to stop sync:", error);
213	    }
214	  };
