216	  public static setup = async (params: Session) => {
217	    await this.clearCryptoStore();
218	
219	    if (MatrixCore.syncService) await MatrixCore.syncService.stop();
220	    MatrixCore.instance = null;
221	    MatrixCore.syncService = null;
222	
223	    MatrixStorage.saveLoginCredentials({
224	      accessToken: params.accessToken,
225	      refreshToken: params.refreshToken,
226	      userId: params.userId,
227	      deviceId: params.deviceId,
228	      baseUrl: params.homeserverUrl,
229	    });
230	
231	    await this.initialize(params.homeserverUrl);
232	
233	    const client = MatrixCore.getClient();
234	
235	    await client.restoreSession({
236	      accessToken: params.accessToken,
237	      refreshToken: params.refreshToken,
238	      userId: params.userId,
239	      deviceId: params.deviceId,
240	      homeserverUrl: params.homeserverUrl,
241	      oidcData: undefined,
242	      slidingSyncVersion: SlidingSyncVersion.Native,
243	    });
244	
245	    try {
246	      const profile = await client.getProfile(params.userId);
247	      MatrixJotaiStore.set(StorageAtoms.cachedProfile, profile);
248	    } catch (error) {
249	      console.warn("Session validation failed:", error);
250	    }
251	
252	    MatrixCore.syncService = await client.syncService().finish();
253	
254	    if (!MatrixCore.syncService) {
255	      throw new Error("Failed to initialize sync service");
256	    }
257	
258	    await MatrixCore.syncService.start();
259	    await client.encryption().waitForE2eeInitializationTasks();
260	
261	    MatrixJotaiStore.set(MatrixAtoms.matrixClient, MatrixCore.instance);
262	    MatrixJotaiStore.set(MatrixAtoms.syncService, MatrixCore.syncService);
263	  };
264	
265	  public static login = async ({
266	    username,
267	    password,
268	  }: LoginWithUsernameAndPasswordData) => {
269	    const client = MatrixCore.getClient();
270	    await client.login(username, password, undefined, undefined);
271	    const session = client.session();
272	
273	    MatrixCore.instance = null;
274	
275	    return session;
276	  };
277	
278	  public static logout = async () => {
279	    // Remove pusher before clearing the session — needs an active Matrix client.
280	    // Ignore errors (user may be offline or permissions already revoked).
281	    const fcmToken = MatrixJotaiStore.get(PushNotificationsAtoms.token);
282	    if (fcmToken) {
283	      try {
284	        await MatrixNotificationService.removePusher(fcmToken);
285	      } catch {}
286	    }
287	
288	    MatrixStorage.clearLoginCredentials();
289	    deleteJotaiStorageAdapter();
290	    await this.clearCryptoStore();
291	    await clearImageCache();
292	    await clearEncryptedImageCache();
293	    await clearEncryptedVideoCache();
294	    await clearMediaEncryptionKey();
295	
296	    //Ignore both errors if it happens, the logout will still happen. These errors can happen if the user is offline.
297	    if (MatrixCore.syncService) {
298	      try {
299	        await MatrixCore.syncService.stop();
300	      } catch {}
301	    }
302	    if (MatrixCore.instance) {
303	      try {
304	        await MatrixCore.instance.logout();
305	      } catch {}
306	    }
307	
308	    MatrixCore.instance = null;
309	    MatrixCore.syncService = null;
310	
311	    resetMatrixAtoms();
312	  };
313	
314	  public static canDeactivateAccount = (): boolean => {
315	    if (!MatrixCore.instance) return false;
316	    return MatrixCore.instance.canDeactivateAccount();
317	  };
318	
319	  public static deactivateAccount = async (
320	    password: string,
321	    eraseData: boolean,
322	  ) => {
323	    const client = MatrixCore.getClient();
324	
325	    // Step 1: attempt with no auth data. SSO / servers that don't require UIA
326	    // will succeed here. Return immediately — password is not needed.
327	    try {
328	      await client.deactivateAccount(undefined, eraseData);
329	      await this.logout();
330	      return;
331	    } catch {
332	      // Password-based server rejected the unauthenticated attempt. Fall through.
333	    }
334	
335	    // Step 2: authenticate with the user-entered password.
336	    const userId = client.userId();
337	    if (!userId) throw new Error("User ID not found");
338	
339	    const authData = new AuthData.Password({
340	      passwordDetails: AuthDataPasswordDetails.create({
341	        identifier: userId,
342	        password,
343	      }),
344	    });
345	
346	    await client.deactivateAccount(authData, eraseData);
347	    await this.logout();
348	  };
349	}
